-- =====================================================================\n-- V14: Soporte para Document Storage, Notificaciones y Fase A Fixes\n-- =====================================================================\n\n-- ---------------------------------------------------------------------\n-- Fix A1: Recovery Account (control de saldo)\n-- Aseguramos que las cuentas se creen en 0 si no existen\n-- (la lógica de incremento se maneja en el servicio).\n-- ---------------------------------------------------------------------\n-- (No requiere cambio de esquema, ya existe la tabla)\n\n-- ---------------------------------------------------------------------\n-- Fix A3: Change Orders -> Billing Projection\n-- ---------------------------------------------------------------------\nCREATE TABLE billing_contract_projection (\n  tenant_id         uuid NOT NULL,\n  contract_id       uuid NOT NULL,\n  original_amount   numeric(18,2) NOT NULL,\n  approved_co_amount numeric(18,2) NOT NULL DEFAULT 0,\n  effective_amount  numeric(18,2) NOT NULL,\n  updated_at        timestamptz NOT NULL DEFAULT now(),\n  PRIMARY KEY (tenant_id, contract_id)\n);\n\nALTER TABLE billing_contract_projection ENABLE ROW LEVEL SECURITY;\nCREATE POLICY ti_billing_contract ON billing_contract_projection\n  USING (tenant_id = current_setting('app.tenant_id')::uuid);\n\n-- ---------------------------------------------------------------------\n-- Feature: Document Storage\n-- ---------------------------------------------------------------------\nALTER TABLE document\n  ADD COLUMN file_name varchar(300),\n  ADD COLUMN content_type varchar(100),\n  ADD COLUMN size_bytes bigint,\n  ADD COLUMN storage_provider varchar(40) DEFAULT 'LOCAL',\n  ADD COLUMN storage_key varchar(500);\n\n-- ---------------------------------------------------------------------\n-- Feature: Notification Worker (Retry & Errors)\n-- ---------------------------------------------------------------------\nALTER TABLE notification_outbox\n  ADD COLUMN retry_count smallint NOT NULL DEFAULT 0,\n  ADD COLUMN last_error text,\n  ADD COLUMN next_retry_at timestamptz NOT NULL DEFAULT now();\n\nCREATE INDEX idx_notification_pending\n  ON notification_outbox (next_retry_at)\n  WHERE sent_at IS NULL AND retry_count < 5;